class DataService {
    constructor() {
        this.dataPath = 'data/predictions.json';
    }

    /**
     * Fetches the latest stock prediction data generated by autoupdate workflows.
     * Appends a timestamp to prevent browser caching of stale data.
     */
    async fetchLatestData() {
        try {
            const cacheBuster = new Date().getTime();
            const response = await fetch(`${this.dataPath}?t=${cacheBuster}`);
            
            if (!response.ok) {
                throw new Error(`HTTP error! Status: ${response.status}`);
            }
            
            const data = await response.json();
            return data;
        } catch (error) {
            console.error('Failed to load prediction data:', error);
            throw error;
        }
    }
}

window.dataService = new DataService();
